export type StoredFile = {
  fileKey: string;
  fileName: string;
  mimeType: string;
};

export type StoredFileBytes = {
  bytes: Buffer;
  fileName: string;
  mimeType: string;
};

/** A file the browser already uploaded to Blob (lib/direct-blob-upload.ts); `adopt()` verifies it into a StoredFile without re-uploading. */
export type UploadedFileRef = {
  fileKey: string;
  fileName: string;
  mimeType: string;
};

export type FileStorage = {
  save(input: Readonly<{ file: File; folder: string }>): Promise<StoredFile>;
  /** Stores server-generated bytes (e.g. a filled Excel workbook) rather than an upload. */
  saveBuffer(
    input: Readonly<{
      bytes: Buffer;
      fileName: string;
      mimeType: string;
      folder: string;
    }>,
  ): Promise<StoredFile>;
  /**
   * Confirms a file the browser already uploaded directly to storage and returns
   * it in `save()`'s shape. Blob only; local disk rejects any call.
   */
  adopt(input: UploadedFileRef): Promise<StoredFile>;
  read(fileKey: string): Promise<StoredFileBytes>;
};
